INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "それにしてもすばらしいケーキですわね。\nどちらの高名な菓子職人に\n依頼されたのでしょう？", 6, 1032501, 0, "", 103211, 1032501043, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1032501, "", "", 0, 1032501044, 91);
