INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "急に牛乳と卵が欲しいっつうから\n何かと思ったけんど、まさか\nオラのためにこんな立派なケーキ\n用意してくれてただなんてな！", 6, 1033501, 0, "", 103311, 1033501040, 11);
