INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 870, "", 1034501, "", "", 103411, 1034501039, 13);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "わあ……素敵なケーキね！\nえ？　キミが作ったの？\nすごいじゃない！", 4, 1034501, 0, "", 103411, 1034501040, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1034501, "", "", 0, 1034501041, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1034501_001", 0, 1034501, "", "", "vo_adv_1034501", 1034501042, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "麦しゅわに合わないかも……って、\nそんな気を使わなくていいわよ。\nだって、今日は飲むつもりはないもの。", 6, 1034501, 0, "", 103411, 1034501043, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1034501, "", "", 0, 1034501044, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1034501_002", 0, 1034501, "", "", "vo_adv_1034501", 1034501045, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "なんでって、それは……\nキミがお祝いに来てくれるかも、\nなんて思ってたから……", 5, 1034501, 0, "", 103411, 1034501046, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1034501, "", "", 0, 1034501047, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1034501_003", 0, 1034501, "", "", "vo_adv_1034501", 1034501048, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "だから、今日は麦しゅわは封印よ。\n麦しゅわもありの大人な誕生日は、\nキミが大人になってから……ね？", 5, 1034501, 0, "", 103411, 1034501049, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1034501, "", "", 0, 1034501050, 91);
