INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "たい焼きの他にケーキまで\n作れるにゃんて……\nキミって意外と料理上手にゃ？", 6, 1046501, 0, "", 104611, 1046501043, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1046501, "", "", 0, 1046501044, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1046501_002", 0, 1046501, "", "", "vo_adv_1046501", 1046501045, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "にゃにゃ……？\nキミのケーキを見てたら\n新しいたい焼きのアイデアが\nどんどん湧いてきたにゃ！", 6, 1046501, 0, "", 104611, 1046501046, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1046501, "", "", 0, 1046501047, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1046501_003", 0, 1046501, "", "", "vo_adv_1046501", 1046501048, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "にゃっふっふ……\nそれじゃ今度、絶品のたい焼きを\nキミにごちそうしてあげるにゃ！\n楽しみに待ってるといいにゃ♪", 6, 1046501, 0, "", 104611, 1046501049, 11);
