INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "素敵なケーキをありがとう！\nまさかこんな盛大に\nお祝いしてもらえるなんて\n思わなかったわ！", 6, 1052501, 0, "", 105211, 1052501040, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1052501, "", "", 0, 1052501041, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1052501_001", 0, 1052501, "", "", "vo_adv_1052501", 1052501042, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "おめでとうって言ってもらえるだけでも\nうれしいのに、手作りのケーキまで……\n私、あなたにいろんなものを\nもらってばっかりね。", 6, 1052501, 0, "", 105211, 1052501043, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1052501, "", "", 0, 1052501044, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1052501_002", 0, 1052501, "", "", "vo_adv_1052501", 1052501045, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "少しでもお返ししたいけど……\nあなたは何かしてほしいことはある？\nえ？　私の誕生日だから私が\n喜んでくれたらうれしい……？", 5, 1052501, 0, "", 105211, 1052501046, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1052501, "", "", 0, 1052501047, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1052501_003", 0, 1052501, "", "", "vo_adv_1052501", 1052501048, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "私、もう十分に喜んでるわ！\nでも、あなたのそんな言葉を聞いたら\nもう少しわがままを\n言いたくなっちゃうわ。", 5, 1052501, 0, "", 105211, 1052501049, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1052501, "", "", 0, 1052501050, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1052501_004", 0, 1052501, "", "", "vo_adv_1052501", 1052501051, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "ケーキをあーんしてもらってもいい？\n一口だけ、一口だけでいいから！\nいいの？　ありがとう！\n最高の誕生日だわ！", 4, 1052501, 0, "", 105211, 1052501052, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1052501, "", "", 0, 1052501053, 91);
