INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "ゆっくりでいいからがんばって\n騎空団として成長して……\nいつかは蒼い空を自由に旅したいな。\nもちろん、その時はあなたも一緒だよ！", 5, 1057501, 0, "", 105711, 1057501049, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1057501, "", "", 0, 1057501050, 91);
