INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", 870, "", 1070501, "", "", 107011, 1070501039, 13);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "ふむ、よい趣向ですね。\n敬うべき相手を忘れず、恩を忘れず、\n健勝を祝う宴を開く……\n礼節を弁えた人間は好きですよ。", 4, 1070501, 0, "", 107011, 1070501040, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1070501, "", "", 0, 1070501041, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1070501_001", 0, 1070501, "", "", "vo_adv_1070501", 1070501042, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "しかし一時には\n赤子同然だった貴方が\nここまで成長したこと……\nとても喜ばしく思います。", 5, 1070501, 0, "", 107011, 1070501043, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1070501, "", "", 0, 1070501044, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1070501_002", 0, 1070501, "", "", "vo_adv_1070501", 1070501045, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "ただ、そうですね……\n厚意に預かるばかり、\nというのも性に合いませんし。\n何かご褒美をあげましょう。", 5, 1070501, 0, "", 107011, 1070501046, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1070501, "", "", 0, 1070501047, 91);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", 0, "vo_adv_1070501_003", 0, 1070501, "", "", "vo_adv_1070501", 1070501048, 21);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "焦って決めずとも構いません。\n今日は一日、私が飽きるまで\n貴方に付き合ってもらう予定ですから。\nふふ……期待していますよ？", 5, 1070501, 0, "", 107011, 1070501049, 11);
INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES ("", "", "", "", "", 1070501, "", "", 0, 1070501050, 91);
