INSERT INTO `v1_b7d3378d088c7c13407504bbde710fe8ab98aceec901a4dfc0cf60a4457bbccb` VALUES (0, 1, 1, "是非もなし。\n端的に言えば、先輩ちょっと感激した。\n今宵は飲めや食えやの大騒ぎだ。\n朝まで踊り明かすぜ同志、ヒャッハー！", 5, 1110501, 0, "", 111011, 1110501052, 11);
